pm.test("Validate pagination metadata schema", function () {
    const jsonData = pm.response.json();

    // Verify required root-level properties
    pm.expect(jsonData).to.have.property("href");
    pm.expect(jsonData).to.have.property("limit");
    pm.expect(jsonData).to.have.property("next");
    pm.expect(jsonData).to.have.property("offset");
    pm.expect(jsonData).to.have.property("previous");
    pm.expect(jsonData).to.have.property("total");
    pm.expect(jsonData).to.have.property("items");

    // Verify data types
    pm.expect(jsonData.href).to.be.a("string");
    pm.expect(jsonData.limit).to.be.a("number");
    pm.expect(jsonData.next).to.be.a("string");
    pm.expect(jsonData.offset).to.be.a("number");
    pm.expect(jsonData.previous).to.be.null;
    pm.expect(jsonData.total).to.be.a("number");
    pm.expect(jsonData.items).to.be.an("array");
});
pm.test("Album object contains valid properties and types", function () {
    const jsonData = pm.response.json();

    // Guard assertion: ensure items array is not empty before indexing
    pm.expect(jsonData.items).to.be.an("array").that.is.not.empty;

    const album = jsonData.items[0];

    // 1. Verify required properties
    pm.expect(album).to.have.property("album_type");
    pm.expect(album).to.have.property("total_tracks");
    pm.expect(album).to.have.property("external_urls");
    pm.expect(album).to.have.property("href");
    pm.expect(album).to.have.property("id");
    pm.expect(album).to.have.property("images");
    pm.expect(album).to.have.property("name");
    pm.expect(album).to.have.property("release_date");
    pm.expect(album).to.have.property("release_date_precision");
    pm.expect(album).to.have.property("type");
    pm.expect(album).to.have.property("uri");
    pm.expect(album).to.have.property("artists");
   

    // 2. Validate data types
    pm.expect(album.album_type).to.be.a("string");
    pm.expect(album.total_tracks).to.be.a("number"); // Specification integer maps to JS number

    pm.expect(album.external_urls).to.be.an("object");
    pm.expect(album.href).to.be.a("string");
    pm.expect(album.id).to.be.a("string");
    pm.expect(album.images).to.be.an("array");
    pm.expect(album.name).to.be.a("string");
    pm.expect(album.release_date).to.be.a("string");
    pm.expect(album.release_date_precision).to.be.a("string");
    pm.expect(album.type).to.be.a("string");
    pm.expect(album.uri).to.be.a("string");
    pm.expect(album.artists).to.be.an("array");

    // 3. Validate allowed values (Enums)
    pm.expect(album.album_type).to.be.oneOf(["album", "single", "compilation"]);
    pm.expect(album.release_date_precision).to.be.oneOf(["year", "month", "day"]);
    pm.expect(album.type).to.eql("album");
});

